private const val MOSAIC_PROTOCOL_VERSION = __MOSAIC_PROTOCOL_VERSION__
private const val MOSAIC_STATUS_OK = 0

class MosaicRuntimeException(val status: Int, message: String) : RuntimeException(message)

// JNA constructs ABI carrier types reflectively from its own package. These
// classes must therefore have public JVM constructors even though applications
// should treat them as generated implementation details.
class MosaicSizeT(value: Long = 0) :
    IntegerType(Native.SIZE_T_SIZE, value, true) {
    override fun toByte(): Byte = toLong().toByte()
    override fun toShort(): Short = toLong().toShort()
}

@Structure.FieldOrder("ptr", "len")
open class MosaicBytes : Structure() {
    @JvmField var ptr: Pointer? = null
    @JvmField var len: MosaicSizeT = MosaicSizeT()

    class ByValue(pointer: Pointer?, length: Long) : MosaicBytes(), Structure.ByValue {
        init {
            ptr = pointer
            len = MosaicSizeT(length)
            write()
        }
    }
}

@Structure.FieldOrder("ptr", "len", "capacity")
open class MosaicBuffer : Structure() {
    @JvmField var ptr: Pointer? = null
    @JvmField var len: MosaicSizeT = MosaicSizeT()
    @JvmField var capacity: MosaicSizeT = MosaicSizeT()

    class ByValue(source: MosaicBuffer) : MosaicBuffer(), Structure.ByValue {
        init {
            ptr = source.ptr
            len = source.len
            capacity = source.capacity
            write()
        }
    }
}

interface MosaicNativeApi : Library {
    fun mosaic_app_create(
        start: MosaicBytes.ByValue,
        app: PointerByReference,
        initialUpdate: MosaicBuffer,
    ): Int

    fun mosaic_app_dispatch(
        app: Pointer,
        event: MosaicBytes.ByValue,
        update: MosaicBuffer,
    ): Int

    fun mosaic_app_snapshot(app: Pointer, snapshot: MosaicBuffer): Int
    fun mosaic_app_restore(
        app: Pointer,
        snapshot: MosaicBytes.ByValue,
        update: MosaicBuffer,
    ): Int
    fun mosaic_buffer_free(buffer: MosaicBuffer.ByValue)
    fun mosaic_app_destroy(app: Pointer)
}

class MosaicRuntimeHost private constructor(private val api: MosaicNativeApi) : MosaicComposeHost {
    private var handle: Pointer? = null
    private var sequence = 0L
    private var latestUpdate: JsonObject
    private var propsChangedHandler: (() -> Unit)? = null

    init {
        val app = PointerByReference()
        val start = buildJsonObject {
            put("protocolVersion", MOSAIC_PROTOCOL_VERSION)
            put("locale", Locale.getDefault().toLanguageTag())
            put("colorScheme", "system")
            put("textScale", 1.0)
            put("platform", mosaicPlatform())
            put("restoredSnapshot", JsonNull)
        }
        latestUpdate = withJsonInput(start) { input ->
            invoke { output -> api.mosaic_app_create(input, app, output) }
        }.jsonObject
        handle = app.value ?: throw MosaicRuntimeException(
            1,
            "Mosaic runtime returned a null application handle",
        )
    }

    @Synchronized
    override fun props(): Map<String, Any?> = latestUpdate.toKotlinMap()

    @Synchronized
    override fun handleEvent(event: Map<String, Any?>): Map<String, Any?> {
        val app = requireHandle()
        val nextSequence = Math.addExact(sequence, 1L)
        val name = event["name"] as? String
            ?: throw IllegalArgumentException("Mosaic event is missing a string name")
        val envelope = buildJsonObject {
            put("protocolVersion", MOSAIC_PROTOCOL_VERSION)
            put("sequence", nextSequence)
            put("name", name)
            put("payload", event["payload"].toJsonElement())
        }
        val update = withJsonInput(envelope) { input ->
            invoke { output -> api.mosaic_app_dispatch(app, input, output) }
        }.jsonObject
        sequence = nextSequence
        latestUpdate = update
        propsChangedHandler?.invoke()
        return update.toKotlinMap()
    }

    @Synchronized
    fun snapshot(): Map<String, Any?>? = when (
        val value = invoke { output ->
            api.mosaic_app_snapshot(requireHandle(), output)
        }
    ) {
        JsonNull -> null
        is JsonObject -> value.toKotlinMap()
        else -> throw IllegalStateException("Mosaic snapshot is not an object or null")
    }

    @Synchronized
    fun restore(snapshot: Map<String, Any?>): Map<String, Any?> {
        val update = withJsonInput(snapshot.toJsonElement()) { input ->
            invoke { output ->
                api.mosaic_app_restore(requireHandle(), input, output)
            }
        }.jsonObject
        latestUpdate = update
        propsChangedHandler?.invoke()
        return update.toKotlinMap()
    }

    @Synchronized
    override fun setPropsChangedHandler(handler: (() -> Unit)?) {
        propsChangedHandler = handler
    }

    @Synchronized
    override fun close() {
        handle?.let(api::mosaic_app_destroy)
        handle = null
        propsChangedHandler = null
    }

    private fun requireHandle(): Pointer = handle
        ?: throw IllegalStateException("Mosaic runtime is closed")

    private fun withJsonInput(
        value: JsonElement,
        operation: (MosaicBytes.ByValue) -> JsonElement,
    ): JsonElement {
        val encoded = value.toString().encodeToByteArray()
        val memory = if (encoded.isEmpty()) null else Memory(encoded.size.toLong()).also {
            it.write(0, encoded, 0, encoded.size)
        }
        return operation(MosaicBytes.ByValue(memory, encoded.size.toLong()))
    }

    private fun invoke(operation: (MosaicBuffer) -> Int): JsonElement {
        val output = MosaicBuffer()
        val status = operation(output)
        val bytes = consume(output)
        if (status != MOSAIC_STATUS_OK) {
            throw MosaicRuntimeException(status, bytes.decodeToString())
        }
        return Json.parseToJsonElement(bytes.decodeToString())
    }

    private fun consume(buffer: MosaicBuffer): ByteArray {
        buffer.read()
        try {
            val length = buffer.len.toLong()
            require(length <= Int.MAX_VALUE) {
                "Mosaic output exceeds the JVM array limit"
            }
            return if (buffer.ptr == null || length == 0L) {
                ByteArray(0)
            } else {
                buffer.ptr!!.getByteArray(0, length.toInt())
            }
        } finally {
            api.mosaic_buffer_free(MosaicBuffer.ByValue(buffer))
        }
    }

    companion object {
        fun load(): MosaicRuntimeHost? = runCatching {
            val library = System.getProperty("mosaic.app.library")
                ?: System.getenv("MOSAIC_APP_LIBRARY")
                ?: bundledMosaicLibrary()
                ?: "mosaic_app"
            val api = Native.load(library, MosaicNativeApi::class.java)
            MosaicRuntimeHost(api)
        }.onFailure { error ->
            System.err.println("Mosaic Rust runtime unavailable: " + error.message)
        }.getOrNull()
    }
}

private fun bundledMosaicLibrary(): String? {
    val resources = System.getProperty("compose.application.resources.dir") ?: return null
    val fileName = when (mosaicPlatform()) {
        "apple" -> "libmosaic_app.dylib"
        "windows" -> "mosaic_app.dll"
        else -> "libmosaic_app.so"
    }
    return java.io.File(resources, fileName)
        .takeIf { it.isFile }
        ?.absolutePath
}

private fun mosaicPlatform(): String {
    val os = System.getProperty("os.name", "").lowercase(Locale.ROOT)
    return when {
        os.contains("mac") || os.contains("darwin") -> "apple"
        os.contains("win") -> "windows"
        else -> "linux"
    }
}

private fun JsonObject.toKotlinMap(): Map<String, Any?> =
    entries.associate { (key, value) -> key to value.toKotlinValue() }

private fun JsonElement.toKotlinValue(): Any? = when (this) {
    JsonNull -> null
    is JsonObject -> toKotlinMap()
    is JsonArray -> map(JsonElement::toKotlinValue)
    is JsonPrimitive -> booleanOrNull ?: longOrNull ?: doubleOrNull ?: content
}

private fun Any?.toJsonElement(): JsonElement = when (this) {
    null -> JsonNull
    is JsonElement -> this
    is Boolean -> JsonPrimitive(this)
    is Number -> JsonPrimitive(this)
    is String -> JsonPrimitive(this)
    is Map<*, *> -> buildJsonObject {
        this@toJsonElement.forEach { (key, value) ->
            require(key is String) { "Mosaic object keys must be strings" }
            put(key, value.toJsonElement())
        }
    }
    is Iterable<*> -> buildJsonArray {
        this@toJsonElement.forEach { add(it.toJsonElement()) }
    }
    is Array<*> -> buildJsonArray {
        this@toJsonElement.forEach { add(it.toJsonElement()) }
    }
    else -> throw IllegalArgumentException(
        "Unsupported Mosaic event payload value: " +
            this::class.qualifiedName,
    )
}
